static int wait_for_data(SSL *ssl, int ret, int timeout) /* <=== wait_for_data */ 
{
  int err;
  int retval = 1;

  err = SSL_get_error(ssl, ret);

  switch(err)
  {
    case SSL_ERROR_WANT_READ:
    case SSL_ERROR_WANT_WRITE:
      ret = sock_read_ready(ssl, timeout*1000);

      if (ret == -1) {
        retval = 2;
      }

      break;
    default:
      retval = 3;
      long verify_res = SSL_get_verify_result(ssl);
      if (verify_res != X509_V_OK)
        rfbClientLog("Could not verify server certificate: %s.\n",
                     X509_verify_cert_error_string(verify_res));
      break;
   }

  ERR_clear_error();

  return retval;
}

static int sock_read_ready(SSL *ssl, uint32_t ms) /* <=== sock_read_ready */ 
{
	int r = 0;
	fd_set fds;
	struct timeval tv;

	FD_ZERO(&fds);

	FD_SET(SSL_get_fd(ssl), &fds);

	tv.tv_sec = ms / 1000;
	tv.tv_usec = (ms % 1000) * 1000;

	r = select (SSL_get_fd(ssl) + 1, &fds, NULL, NULL, &tv); 

	return r;
}

